pub(super) const LIST_AUDIT_LOG_STATUS200_BODY: &str = "{\"$schema\":\"http://json-schema.org/draft-07/schema#\",\"definitions\":{\"AuditEntry\":{\"description\":\"One row of the append-only audit trail: who did what to which record, and\\nwhen. Rows hold identifiers and fixed action names, never record contents.\",\"properties\":{\"action\":{\"description\":\"What: a fixed action name such as `ssn_revealed` or `user_role_changed`.\",\"type\":\"string\"},\"at\":{\"description\":\"When.\",\"format\":\"date-time\",\"pattern\":\"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-5][0-9]\\\\.[0-9]{3}Z$\",\"type\":\"string\",\"x-forklaunch-date-codec\":{\"kind\":\"utc-milliseconds\",\"projection\":\"value\",\"version\":1}},\"detail\":{\"description\":\"A fixed qualifier (the new role, the field that was read), never a value.\",\"type\":[\"string\",\"null\"]},\"entity_id\":{\"description\":\"Which record: the id of the application, owner, document or user.\",\"type\":[\"string\",\"null\"]},\"id\":{\"format\":\"int64\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"request_id\":{\"description\":\"The request the entry was written in, to find it in the logs.\",\"type\":[\"string\",\"null\"]},\"user_id\":{\"description\":\"Who: the acting user's id. Absent for the scheduled jobs.\",\"type\":[\"string\",\"null\"]}},\"required\":[\"id\",\"at\",\"action\"],\"type\":\"object\",\"x-forklaunch-model\":{\"id\":\"api_contracts::schemas::users::AuditEntry\",\"name\":\"AuditEntry\",\"projection\":\"value\",\"version\":1}}},\"items\":{\"$ref\":\"#/definitions/AuditEntry\"},\"title\":\"Array_of_AuditEntry\",\"type\":\"array\"}";
